def test_column_order(run, x):
    answer = run(x)
    expected = ['Index', 'Element', 'Count'] if x['include_index'] else ['Element', 'Count']
    assert list(answer.columns) == expected

def test_row_count(run, x):
    answer = run(x)
    assert len(answer) == len(x['elements'])

def test_elements_in_order(run, x):
    answer = run(x)
    assert answer['Element'].tolist() == x['elements']

def test_counts(run, x):
    answer = run(x)
    assert answer['Count'].tolist() == [len(element) for element in x['elements']]

def test_index_presence(run, x):
    answer = run(x)
    assert ('Index' in answer.columns) == x['include_index']

def test_index_values(run, x):
    answer = run(x)
    if x['include_index']:
        assert answer['Index'].tolist() == list(range(len(x['elements'])))
    else:
        assert 'Index' not in answer.columns

def test_rowwise_values(run, x):
    answer = run(x)
    actual = list(zip(answer['Element'].tolist(), answer['Count'].tolist()))
    expected = [(element, len(element)) for element in x['elements']]
    assert actual == expected

def test_complete_table(run, x):
    answer = run(x)
    expected = {'Element': list(x['elements']), 'Count': [len(element) for element in x['elements']]}
    if x['include_index']:
        expected = {'Index': list(range(len(x['elements']))), **expected}
    assert answer.to_dict(orient='list') == expected

def test_count_matches_input_row(run, x):
    answer = run(x)
    assert all(answer['Count'].iloc[i] == len(x['elements'][i]) for i in range(len(x['elements'])))

