def test_direct_combination_sum(run, x):
    import itertools
    import math
    answer = run(x)
    expected = 0.0
    numbers = x['numbers']
    for size in range(1, len(numbers) + 1):
        for combination in itertools.combinations(numbers, size):
            product = 1
            for value in combination:
                product *= value
            expected += math.log(product)
    assert isinstance(answer, float) and math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)

def test_coefficient_identity(run, x):
