    answer = run(x)
    numbers = x['numbers']
    expected = 0.0 if not numbers else 2 ** (len(numbers) - 1) * sum(math.log(value) for value in numbers)
    assert isinstance(answer, float) and math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)

